<?php

namespace App\Models;

use Illuminate\Database\Eloquent\Model;
use LogicException;

/**
 * A student's term results, locked as issued.
 *
 * Once written, the figures never change: `data` and its hash are immutable
 * and a correction is a new row with the next version. Only the supersession
 * and verification markers may be set afterwards.
 */
class TermSnapshot extends Model
{
    use BelongsToTenant;

    public const PROVENANCE = [
        'system_generated' => 'Generated by this school on SchoolPilot',
        'manually_entered' => 'Entered by hand by this school',
        'imported_verified_electronic' => 'Imported and verified electronically',
        'imported_verified_upload' => 'Imported from an upload and verified',
        'uploaded_unverified' => 'Uploaded, not yet verified',
        'discrepancy' => 'Flagged: does not match its source',
    ];

    /** Columns that may change after the snapshot is written. */
    private const MUTABLE = ['superseded_at', 'verified_by', 'verified_at', 'provenance', 'updated_at'];

    protected $fillable = [
        'school_id', 'student_id', 'term_id', 'session_id', 'class_id',
        'session_name', 'term_name', 'class_name', 'version', 'source', 'provenance',
        'broadsheet_version', 'partial_term', 'data', 'data_hash', 'locked_by', 'locked_at',
        'correction_reason', 'correction_approved_by', 'superseded_at', 'verified_by', 'verified_at',
    ];

    protected $casts = [
        'partial_term' => 'boolean',
        'locked_at' => 'datetime',
        'superseded_at' => 'datetime',
        'verified_at' => 'datetime',
    ];

    protected $hidden = ['data'];

    protected static function booted(): void
    {
        static::updating(function (TermSnapshot $snapshot) {
            $changed = array_diff(array_keys($snapshot->getDirty()), self::MUTABLE);

            if ($changed !== []) {
                throw new LogicException('A locked term snapshot cannot be edited. Record a correction instead.');
            }
        });

        static::deleting(fn () => throw new LogicException('Term snapshots are never deleted.'));
    }

    /** @return array<string, mixed> */
    public function figures(): array
    {
        return json_decode($this->data, true) ?? [];
    }

    public function intact(): bool
    {
        return hash_equals($this->data_hash, hash('sha256', $this->data));
    }

    public function isVerified(): bool
    {
        return ! in_array($this->provenance, ['uploaded_unverified', 'discrepancy'], true);
    }

    public function scopeCurrent($query)
    {
        return $query->whereNull('superseded_at');
    }

    public function student()
    {
        return $this->belongsTo(Student::class);
    }
}
